import {STOCK_FIRE_RED_SHA} from './verified-frlg.js';
const BASE=0x08000000;
const names=['General door','Single sliding door','Double sliding door','Pallet house','Oak’s lab','Viridian house','Pewter house','Saffron house','Silph Co.','Cerulean house','Lavender house','Vermilion house','Fan Club / SS Anne warp','Celadon department store','Fuchsia house','Safari Zone','Cinnabar lab','Sevii 1–3 house','Joyful Game Corner','One Island Pokémon Centre','Sevii 4–5 house','Four Island day care','Rocket Warehouse','Sevii 6–7 house','Department store elevator','Cable Club','Hideout elevator','Silph elevator','Teleporter','SS Anne','Trainer Tower lobby elevator','Trainer Tower roof elevator'];
export function doorAnimationProfile(hash){if(hash===STOCK_FIRE_RED_SHA)return{table:0x35b5d8,timing:0x35b488};throw Error('The selected ROM supports no compatible source animation table.');}
export function validateDoorAnimations(edits){if(edits===undefined)return;if(!edits||Array.isArray(edits)||Object.keys(edits).length>16)throw Error('Invalid door animation edits.');for(const [hash,e]of Object.entries(edits)){if(!/^[a-f0-9]{64}$/.test(hash)||!e||!e.doors||Object.keys(e.doors).length>96||e.timing!==undefined&&(!Number.isInteger(e.timing)||e.timing<1||e.timing>30))throw Error('Invalid native door settings.');for(const [id,row]of Object.entries(e.doors)){if(!/^\d+$/.test(id)||+id>95||!row||![0,1].includes(row.size)||![0,1].includes(row.sound)||!Array.isArray(row.tiles)||row.tiles.length!==(row.size?768:384)||row.tiles.some(n=>!Number.isInteger(n)||n<0||n>255))throw Error('Invalid native door frame data.');if(+id>=32&&(!Number.isInteger(row.metatile)||row.metatile<0||row.metatile>1023||typeof row.name!=='string'||!row.name.trim()||row.name.length>80||!Array.isArray(row.palettes)||row.palettes.length!==8||row.palettes.some(n=>!Number.isInteger(n)||n<0||n>15)))throw Error('A new door style needs a metatile, name and eight palette indices.');}}}
export function readDoorAnimations(reader,hash){const profile=doorAnimationProfile(hash),r=reader;const expected=[[0xffff,0,128,256],[0xffff,0,256,512],[256,128,0,0xffff],[512,256,0,0xffff]];for(let seq=0;seq<4;seq++){for(let frame=0;frame<4;frame++)if(r.u8(profile.timing+seq*20+frame*4)!==4||r.u16(profile.timing+seq*20+frame*4+2)!==expected[seq][frame])throw Error('Native door timing layout failed verification.');if(r.u32(profile.timing+seq*20+16)!==0)throw Error('Native door timing terminator is invalid.');}const doors=names.slice(0,profile.count||32).map((name,id)=>{const at=profile.table+id*12,metatile=r.u16(at),sound=r.u8(at+2),size=r.u8(at+3),tiles=r.u32(at+4)-BASE,palette=r.u32(at+8)-BASE,length=size?768:384;if(sound>1||size>1||tiles<512||tiles+length>r.bytes.length||palette<512||palette+8>r.bytes.length)throw Error('Native door graphics failed verification.');const palettes=Array.from(r.bytes.slice(palette,palette+8));if(palettes.some(n=>n>15))throw Error('Native door palettes failed verification.');return{id,name,metatile,sound,size,palettes,tiles:Array.from(r.bytes.slice(tiles,tiles+length)),address:at};});if(r.u32(profile.table+doors.length*12+4)!==0)throw Error('Native door table terminator is invalid.');return{profile,doors};}
export function doorFramePixels(door,frame){if(!Number.isInteger(frame)||frame<0||frame>2)throw Error('Choose one of three animated frames.');const height=door.size?32:16,out=new Uint8Array(16*height),bytesPer=door.size?256:128;for(let y=0;y<height;y++)for(let x=0;x<16;x++){const tile=Math.floor(y/8)*2+Math.floor(x/8),index=frame*bytesPer+tile*32+(y%8)*4+Math.floor(x%8/2),b=door.tiles[index];out[y*16+x]=x%2?b>>>4:b&15;}return out;}
export function paintDoorPixel(door,frame,x,y,colour){if(![frame,x,y,colour].every(Number.isInteger)||frame<0||frame>2||x<0||x>15||y<0||y>=(door.size?32:16)||colour<0||colour>15)throw Error('Invalid door pixel.');const tile=Math.floor(y/8)*2+Math.floor(x/8),at=frame*(door.size?256:128)+tile*32+(y%8)*4+Math.floor(x%8/2);door.tiles[at]=x%2?(door.tiles[at]&15)|(colour<<4):(door.tiles[at]&240)|colour;}
export function installDoorAnimations(project,reader,hash,output,bindings=new Map()){let edits=project.doorAnimations?.[hash];if(!edits&&!bindings.size)return[];if(edits)validateDoorAnimations({[hash]:edits});const native=readDoorAnimations(reader,hash),reports=[];edits=structuredClone(edits||{doors:{}});for(const [metatile,styleId]of bindings){const original=native.doors[styleId],row=edits.doors[styleId],template=original?{...original,...row}:row;if(!template)throw Error('A portal references a missing native door style.');const nativeMatch=native.doors.find(d=>d.metatile===metatile),draftMatch=Object.entries(edits.doors).find(([id,r])=>+id>=32&&r.metatile===metatile);if(nativeMatch){if(nativeMatch.id===styleId)continue;throw Error('This doorway metatile already has a different native animation. Use a separate doorway tile.');}if(draftMatch){if(+draftMatch[0]===styleId)continue;throw Error('Two door styles target the same exported metatile.');}const next=Array.from({length:64},(_,i)=>i+32).find(i=>!edits.doors[i]);if(next===undefined)throw Error('This ROM export exceeds 64 additional door styles.');edits.doors[next]={name:template.name||'Portal door',metatile,size:template.size,sound:template.sound,palettes:[...template.palettes],tiles:[...template.tiles]};}validateDoorAnimations({[hash]:edits});for(const [id,row]of Object.entries(edits.doors)){const old=native.doors[+id];if(!old){if(+id<32)throw Error('This source has no door style '+id+'.');continue;}if(row.size!==old.size)throw Error('Native door dimensions cannot change.');if(row.tiles.some((n,i)=>n!==old.tiles[i])){const raw=new Uint8Array(row.tiles.length+(row.size?0:128));raw.set(row.tiles);const at=output.allocate(raw,'Door frames: '+old.name);output.int(old.address+4,BASE+at);}if(row.sound!==old.sound)output.write(old.address+2,Uint8Array.of(row.sound));reports.push('Door frames: '+old.name+' · shared native style');}const added=Object.entries(edits.doors).filter(([id])=>+id>=32).sort((a,b)=>+a[0]-+b[0]);if(added.length){const used=new Set(native.doors.map(d=>d.metatile)),table=new Uint8Array((native.doors.length+1+added.length)*12),tv=new DataView(table.buffer);table.set(output.bytes.subarray(native.profile.table,native.profile.table+native.doors.length*12));for(const [i,[id,row]]of added.entries()){if(used.has(row.metatile))throw Error('Two door styles use metatile '+row.metatile+'.');used.add(row.metatile);const raw=new Uint8Array(row.tiles.length+(row.size?0:128));raw.set(row.tiles);const at=native.doors.length*12+i*12;tv.setUint16(at,row.metatile,true);table[at+2]=row.sound;table[at+3]=row.size;tv.setUint32(at+4,BASE+output.allocate(raw,'New door frames: '+row.name),true);tv.setUint32(at+8,BASE+output.allocate(Uint8Array.from(row.palettes),'New door palettes'),true);reports.push('Registered door style: '+row.name+' · metatile '+row.metatile);}const refs=[];for(let at=512;at+4<=reader.bytes.length;at+=4)if(reader.u32(at)===BASE+native.profile.table)refs.push(at);if(!refs.length||refs.length>16)throw Error('Native door table references failed verification.');const at=output.allocate(table,'Expanded native door styles');for(const ref of refs)output.int(ref,BASE+at);}
 if(edits.timing!==undefined){for(let seq=0;seq<4;seq++)for(let f=0;f<4;f++)output.write(native.profile.timing+seq*20+f*4,Uint8Array.of(edits.timing));reports.push('Door timing: '+edits.timing+' ticks · all native styles');}return reports;}
